mapper.select:
SELECT id, group_id, sequence_no, author_user_id, sender_type, sender_agent_id,
       client_message_id, message_type, content, mentions, reply_to_message_id, created_at
FROM messages
WHERE group_id = #{groupId} AND sequence_no > #{afterSequence}
ORDER BY sequence_no ASC LIMIT #{limit}

SELECT m.id, m.group_id, m.sequence_no, m.author_user_id, m.sender_type, m.sender_agent_id,
       m.client_message_id, m.message_type, m.content, m.mentions, m.reply_to_message_id, m.created_at
FROM messages m
INNER JOIN chat_groups rg ON rg.id = m.group_id
WHERE rg.project_id = #{projectId}
  AND m.group_id IN
  #{groupId}
  AND JSON_UNQUOTE(JSON_EXTRACT(m.content, '$.text')) LIKE CONCAT('%', #{q}, '%')
ORDER BY m.sequence_no DESC LIMIT #{limit}

mapper.delete:
DELETE FROM messages
WHERE group_id IN
#{gid}
  AND id NOT IN (
    SELECT rid FROM (
        SELECT reply_to_message_id AS rid
        FROM messages
        WHERE group_id IN
        #{rid}
          AND reply_to_message_id IS NOT NULL
    ) AS tmp
  )
